import sys, re

def main():
    if len(sys.argv) != 2:
        sys.exit(1)
    path = sys.argv[1]
    try:
        with open(path, 'r', encoding='utf-8') as f:
            text = f.read()
    except Exception:
        sys.exit(1)
    required = ['## 决策', '## 方向选择', '## 不选方向', '## 依据与止损']
    positions = []
    for h in required:
        idx = text.find(h)
        if idx == -1:
            sys.exit(1)
        positions.append(idx)
    if positions != sorted(positions):
        sys.exit(1)
    sections = {}
    for i, h in enumerate(required):
        start = positions[i] + len(h)
        end = positions[i+1] if i+1 < len(required) else len(text)
        content = text[start:end].strip()
        if not content:
            sys.exit(1)
        sections[h] = content
    if not re.search(r'[^\s]', sections['## 方向选择']):
        sys.exit(1)
    if not re.search(r'[^\s]', sections['## 不选方向']):
        sys.exit(1)
    basis = sections['## 依据与止损']
    if '依据' not in basis or '止损' not in basis:
        sys.exit(1)
    sys.exit(0)

if __name__ == '__main__':
    main()

