import sys, re

def main():
    if len(sys.argv) != 2:
        sys.exit(1)
    path = sys.argv[1]
    try:
        with open(path, 'r', encoding='utf-8') as f:
            text = f.read()
    except Exception:
        sys.exit(1)
    lines = text.splitlines()
    # 找表头行：包含 token、失败次数、返工次数 三个词（不区分大小写，允许空格）
    header_idx = None
    for i, line in enumerate(lines):
        low = line.lower()
        if 'token' in low and '失败次数' in line and '返工次数' in line:
            header_idx = i
            break
    if header_idx is None:
        sys.exit(1)
    # 解析表头列名
    header = lines[header_idx]
    # 简单按 | 分割，去除首尾空白和空段
    cols = [c.strip() for c in header.split('|')]
    cols = [c for c in cols if c != '']
    if len(cols) < 3:
        sys.exit(1)
    # 找三列索引
    idx_token = idx_fail = idx_rework = None
    for j, c in enumerate(cols):
        cl = c.lower()
        if 'token' in cl:
            idx_token = j
        elif '失败次数' in c:
            idx_fail = j
        elif '返工次数' in c:
            idx_rework = j
    if None in (idx_token, idx_fail, idx_rework):
        sys.exit(1)
    # 检查后续行（直到表格结束：空行或非 | 开头）
    data_rows = 0
    for line in lines[header_idx+1:]:
        stripped = line.strip()
        if not stripped:
            break
        if not stripped.startswith('|'):
            break
        # 跳过对齐行（如 |---|---|）
        if re.match(r'^\|?[\s:-]+\|', stripped):
            continue
        cells = [c.strip() for c in stripped.split('|')]
        cells = [c for c in cells if c != '']
        if len(cells) <= max(idx_token, idx_fail, idx_rework):
            continue
        def is_number(s):
            try:
                float(s)
                return True
            except ValueError:
                return False
        if is_number(cells[idx_token]) and is_number(cells[idx_fail]) and is_number(cells[idx_rework]):
            data_rows += 1
    if data_rows >= 1:
        sys.exit(0)
    else:
        sys.exit(1)

if __name__ == '__main__':
    main()

